import 'server-only'

import { createAdminSupabase } from '@/lib/supabase/admin'
import type { NatalChart } from '@/types/blueprint'
import collectiveData from './data/collective-cycles.json'
import slowData from './data/slow-longitudes.json'
import {
  addDays,
  daysBetween,
  detectPersonalTransits,
  natalPointsFromChart,
  shortDate,
  type SlowLongitudeSeries,
} from './detect'
import { relevantCycles, worthShowingToday } from './status'
import type { SkyCycle, SkyCycleStatus } from './types'

/** Generated by scripts/generate-sky-cycles.mts from our own detector. */
const COLLECTIVE: SkyCycle[] = (collectiveData as { cycles: SkyCycle[] }).cycles

const SLOW = slowData as { from: string; lons: number[][] }

/** Slow-planet longitudes for [from, to], clipped to the generated table. */
function slowSeries(from: string, to: string): SlowLongitudeSeries {
  const startIdx = Math.max(0, daysBetween(SLOW.from, from))
  const endIdx = Math.min(SLOW.lons.length - 1, daysBetween(SLOW.from, to))
  const series: SlowLongitudeSeries = []
  for (let i = startIdx; i <= endIdx; i++) {
    const [jupiter, saturn, uranus, neptune, pluto] = SLOW.lons[i]
    series.push({ date: addDays(SLOW.from, i), lons: { jupiter, saturn, uranus, neptune, pluto } })
  }
  return series
}

function isNatalChart(value: unknown): value is NatalChart {
  if (!value || typeof value !== 'object') return false
  const chart = value as Partial<NatalChart>
  return typeof chart.sun?.longitude === 'number' && typeof chart.moon?.longitude === 'number'
}

/** Personal transits from roughly a year ago to half a year ahead. */
export function personalCyclesFor(chart: NatalChart, today: string): SkyCycle[] {
  return detectPersonalTransits(slowSeries(addDays(today, -400), addDays(today, 200)), natalPointsFromChart(chart))
}

export function collectiveCycles(): SkyCycle[] {
  return COLLECTIVE
}

export interface CycleEcho {
  /** The previous time this kind of cycle happened, if we know it. */
  previous: { startDate: string; endDate: string; label: string } | null
  /** Included journal entries and Stelloquy saves during the previous time. */
  previousEntryCount: number
  previousEntryTitle: string | null
  /** Included entries written so far during this cycle (active or ended). */
  entriesThisTime: number
  /** A journal pattern Kairos already found for this kind of cycle. */
  patternSummary: string | null
}

export interface SkyCycleItem extends SkyCycleStatus {
  echo: CycleEcho
}

function previousOf(cycle: SkyCycle, all: SkyCycle[]): SkyCycle | null {
  let best: SkyCycle | null = null
  for (const c of all) {
    if (c.familyKey !== cycle.familyKey || c.id === cycle.id) continue
    if (c.endDate >= cycle.startDate) continue
    if (!best || c.endDate > best.endDate) best = c
  }
  return best
}

async function countIncluded(
  profileId: string,
  from: string,
  to: string,
): Promise<{ count: number; latestTitle: string | null }> {
  const admin = createAdminSupabase()
  const [entries, captures] = await Promise.all([
    admin
      .from('journal_entries')
      .select('title, body, entry_date', { count: 'exact' })
      .eq('user_id', profileId)
      .eq('include_in_insights', true)
      .gte('entry_date', from)
      .lte('entry_date', to)
      .order('entry_date', { ascending: false })
      .limit(1),
    admin
      .from('oracle_captures')
      .select('id', { count: 'exact', head: true })
      .eq('user_id', profileId)
      .eq('include_in_insights', true)
      .gte('created_at', `${from}T00:00:00Z`)
      .lte('created_at', `${to}T23:59:59Z`),
  ])
  if (entries.error || captures.error) throw new Error('Could not load journal for this cycle')
  const latest = entries.data?.[0]
  const latestTitle = latest
    ? (latest.title?.trim() || latest.body.trim().split('\n')[0] || '').slice(0, 80) || null
    : null
  return { count: (entries.count ?? 0) + (captures.count ?? 0), latestTitle }
}

async function patternSummaryFor(profileId: string, cycle: SkyCycle): Promise<string | null> {
  if (cycle.kind !== 'retrograde' || !cycle.planet) return null
  const admin = createAdminSupabase()
  const { data } = await admin
    .from('user_pattern_insights')
    .select('summary, ai_summary, sample_size')
    .eq('user_id', profileId)
    .eq('pattern_type', 'retrograde')
    .eq('pattern_key', cycle.planet)
    .maybeSingle()
  if (!data || data.sample_size < 2) return null
  const text = (data.ai_summary ?? data.summary ?? '').trim()
  if (!text) return null
  return text.length > 220 ? `${text.slice(0, 217)}…` : text
}

async function echoFor(profileId: string, status: SkyCycleStatus, all: SkyCycle[], today: string): Promise<CycleEcho> {
  const prev = previousOf(status.cycle, all)
  const [prevCounts, thisTime, patternSummary] = await Promise.all([
    prev ? countIncluded(profileId, prev.startDate, prev.endDate) : Promise.resolve({ count: 0, latestTitle: null }),
    status.phase === 'upcoming'
      ? Promise.resolve({ count: 0, latestTitle: null })
      : countIncluded(profileId, status.cycle.startDate, status.cycle.endDate < today ? status.cycle.endDate : today),
    patternSummaryFor(profileId, status.cycle),
  ])
  return {
    previous: prev
      ? { startDate: prev.startDate, endDate: prev.endDate, label: `${shortDate(prev.startDate)} to ${shortDate(prev.endDate)}` }
      : null,
    previousEntryCount: prevCounts.count,
    previousEntryTitle: prevCounts.latestTitle,
    entriesThisTime: thisTime.count,
    patternSummary,
  }
}

export async function loadNatalChart(profileId: string): Promise<NatalChart | null> {
  const admin = createAdminSupabase()
  const { data } = await admin.from('user_profiles').select('natal_chart').eq('id', profileId).maybeSingle()
  return isNatalChart(data?.natal_chart) ? data.natal_chart : null
}

/** All cycles (collective plus this member's personal ones) overlapping [from, to]. */
export async function loadCyclesInRange(profileId: string, from: string, to: string, today: string): Promise<SkyCycle[]> {
  const chart = await loadNatalChart(profileId)
  const personal = chart ? personalCyclesFor(chart, today) : []
  return [...COLLECTIVE, ...personal]
    .filter((c) => c.endDate >= from && c.startDate <= to)
    .sort((a, b) => a.startDate.localeCompare(b.startDate))
}

/** What Today shows: up to `limit` cycles with a heads-up, under way, or just ended. */
export async function loadTodaySkyCycles(profileId: string, today: string, limit = 3): Promise<SkyCycleItem[]> {
  const chart = await loadNatalChart(profileId)
  const personal = chart ? personalCyclesFor(chart, today) : []
  const all = [...COLLECTIVE, ...personal]
  const statuses = relevantCycles(all, today).filter((s) => worthShowingToday(s, today))
  const chosen = statuses.slice(0, limit)
  return Promise.all(chosen.map(async (s) => ({ ...s, echo: await echoFor(profileId, s, all, today) })))
}
